/* tabla.h — the tabla: recorded strokes (step 4: ElectroNick chose recordings over modal synthesis), played back.
 *
 * Data (generated by tools/tabla_data/build_samples.py from data/tabla/): strokes (tabla_strokes.h), each with one or
 * more takes, IMA ADPCM in the app image (tabla_samples.h); bols (tabla_bols.h), one or two strokes played together.
 *  - the dayan's takes are retuned to Sa by resampling (4-point Hermite interpolation): the recordings' dayan sits at
 *    315.2 Hz; it plays at the Sa folded into 190..380 Hz (Sa A3 -> 220 Hz);
 *  - the bayan keeps its own pitch (stored at half the rate);
 *  - a stroke chokes the one still ringing on the same drum (8 ms fade): Ge rings on under the dayan's strokes;
 *  - takes of a stroke are rotated (round robin from a random start), with +-5 % of level;
 *  - dynamic 0..127: level, and a softer stroke is darker (a one-pole low-pass, ~22 kHz at 127 down to 2 kHz at 0).
 *
 * Playing: tabla_trigger(bol, dynamic, offset) queues a bol `offset` samples after the start of the next
 * tabla_render (offsets past that render carry over to the following ones). The taal engine (step 6) calls it from the
 * audio path; TABLA_P_HIT does the same at offset 0 for the host's scenarios.
 * Parameters (tabla_set_param), besides the shared tuning (DSP_P_A4_DHZ, DSP_P_SA_CENTS):
 *   TABLA_P_HIT         bol | dynamic << 8        play a bol now (bol: tabla_bol_find)
 *   TABLA_P_STOP        any                       every voice fades out in 8 ms
 *   (read only) TABLA_P_DAYAN_DHZ                 the dayan's pitch now, tenths of a hertz */
#pragma once
#include <stdint.h>
#include "dsp/dsp.h"
#include "dsp/tuning.h"
#include "tabla/tabla_strokes.h"

#define TABLA_NVOICE 6                     /* 3 per drum: one ringing, the ones still fading out */
#define TABLA_QUEUE 16
#define TABLA_DAYAN_REC_HZ 315.2f          /* the recordings' dayan (Tun's fundamental, step 4) */
#define TABLA_DAYAN_LO_HZ 190.0f           /* the dayan plays at Sa folded into [LO, 2 LO) */
#define TABLA_LEVEL 0.35f                  /* a full-scale take at dynamic 127, level 0 dB: its peak in the output */
#define TABLA_CHOKE_S 0.008f

enum { TABLA_DAYAN, TABLA_BAYAN, TABLA_NDRUM };

enum {
    TABLA_P_HIT = DSP_P_MODULE,
    TABLA_P_STOP,
    TABLA_P_DAYAN_DHZ,
    TABLA_P_END
};

typedef struct {
    tuning_t tuning;
    uint32_t seed;                         /* round robin's start and the level variation */
} tabla_config_t;

typedef struct {
    const uint8_t *src;                    /* ADPCM, low nibble first */
    uint32_t n, i;                         /* samples in the take, decoded so far */
    int32_t pred, idx;                     /* the decoder's state */
    float h[4];                            /* the last four decoded samples (h[3] newest); output between h[1], h[2] */
    float frac;                            /* position past h[1], 0..1 */
    float rate;                            /* the take's rate / DSP_FS: 1 (dayan) or 0.5 (bayan) */
    float gain;                            /* level (stroke, bol, dynamic, variation) * TABLA_LEVEL * Q23 */
    float fade, fade_step;                 /* 1 while ringing; falls to 0 once choked */
    float lpa, lp;                         /* the soft stroke's low-pass: coefficient (0 = off), state */
    uint32_t age;                          /* trigger order (the oldest voice is stolen) */
    uint8_t drum, active;
} tabla_voice_t;

typedef struct {
    uint8_t bol, dyn;
    int32_t at;                            /* samples from the start of the next render */
} tabla_hit_t;

typedef struct {
    tabla_config_t cfg;
    tuning_t tuning;
    float dayan_hz, dayan_step;            /* the dayan's pitch, its resampling step */
    tabla_voice_t v[TABLA_NVOICE];
    tabla_hit_t q[TABLA_QUEUE];            /* pending hits, in order of `at` */
    int32_t nq;
    uint8_t next_take[TABLA_NSTROKE];
    uint32_t rng, age;
    uint32_t dropped;                      /* hits lost to a full queue (should stay 0) */
} tabla_t;

void tabla_init(tabla_t *m, const tabla_config_t *cfg);   /* cfg NULL: default tuning, seed */
void tabla_set_param(tabla_t *m, int param_id, int32_t value);
int32_t tabla_get_param(const tabla_t *m, int param_id);
void tabla_render(tabla_t *m, int32_t *out, int n_samples);   /* adds into out (mono Q23) */
/* queue a bol (0..tabla_bol_count()-1), dynamic 0..127, `offset` samples into the next render; 0 ok, -1 dropped */
int tabla_trigger(tabla_t *m, int bol, int dynamic, int32_t offset);

/* the bol table */
int tabla_bol_count(void);
const char *tabla_bol_name(int bol);
int tabla_bol_find(const char *name);      /* ignoring case; -1 if none */
int tabla_bol_strokes(int bol, int *stroke, int *level255);   /* fills up to 2; returns how many */
const char *tabla_stroke_name(int stroke);
int tabla_stroke_drum(int stroke);
/* decode every take and compare it with the generator's hash: the number of takes that differ (0 expected) */
int tabla_selftest(void);
/* sizes, for the reports */
uint32_t tabla_data_bytes(void);
